-- Movimientos (documentos) de las subcajas de la organización 3 (Futura Farma - Mavisa), del archivo
-- «CON_MOVIMIENTOS_SUBCAJAS.xls» (5495 movimientos: 2287 de la 3-01, 3208 de la 3-02). Se ejecuta después del script 121 (cajas y subcajas).
--   1. Cada movimiento es un documento de su subcaja: la línea del documento es el número de MOVIMIENTO. Si ya existe NO se
--      crea: se actualiza. Los documentos de las subcajas cerradas (liquidadas) también se cargan.
--   2. Columnas nuevas en caja_documentos (vienen con datos y no estaban en la base de datos):
--      origen_anterior (marca MIGRADO), movimiento_anterior (MOVIMIENTO), tipo_documento_anterior (TIPO_DOCUMENTO), tipo_documento_id (tipo de documento del catálogo de compras), clasificacion_anterior (CLASIFICACION), clasificacion_id (clasificación del catálogo de compras), proveedor_id (PROVEEDOR), valor_anterior (VALOR), total_factura (TOTAL_FACTURA), moneda_integracion (MONEDA_INTEGRACION), valor_cambio_anterior (VALOR_CAMBIO), anticipo (ANTICIPO (S/N)), propina (PROPINA), porcentaje_retencion (PCT_RETENCION), aplica_inguat (APLICA_INGUAT (S/N)), cuenta_codigo_anterior (CUENTA_MOVTO), version_cuenta_anterior (VERSION), cuenta_propina_id (CUENTA_PROPINA), cuenta_propina_codigo_anterior (CUENTA_PROPINA), version_propina_anterior (VERSION_PROPINA), tipo_factura (TIPO_FACTURA), tipo_gasto_anterior (TIPO_GASTO), persona_gasto (PERSONA_GASTO), exento_anterior (EXENTO), estado_anterior (ESTADO), valor_mi (VALOR_MI), nombre_recibe (NOMBRE_RECIBE), fecha_ingreso_anterior (FECHA_INGRESO), fecha_ing_anterior (FECHA_ING).
--      Columnas vacías en todas las filas (no se agregan): CUENTA, AÑO_POLIZA, MES_POLIZA, POLIZA, COMPRA, FORMULARIO_SAT, DOCTO_TMP, CENTRO_COSTO, DOCUMENTO_COMPLETO, APORTACIONES, FECHA_APORTACIONES, TOTAL_DISPONIBLE_CAJA, TOTAL_RESTANTE_CAJA, PRECIO_SUPER, PRECIO_REGULAR, PRECIO_DIESEL, CUENTA_IVA_NO_DEDUCIBLE, VERSION_IVA_NO_DEDUCIBLE, TIPO_DOCUMENTO2, TIPO_GASTO_INTEGRA, TIPO_GASTO_DETALLE, COMBUSTIBLES, TIPO_CAJA, CORTE_CAJA, AÑO_CORTE, MES_CORTE, DIA_CORTE, VALOR_CORTE, CORTE, RUBRO, TIPO_RUBRO.
--   Equivalencias: SERIE_DOCUMENTO y DOCUMENTO; FECHA_DOCUMENTO; PROVEEDOR por su código (NIT y nombre del proveedor);
--   TOTAL = total del documento (en la factura con retención incluye la retención; VALOR, lo pagado, queda en valor_anterior);
--   TIPO_DOCUMENTO 3 = factura electrónica, 9 = pequeño contribuyente, 11 = recibo, 6 y 10 = otro; CLASIFICACION 2 y 6 =
--   servicios, 4 = bienes, 5 = combustible, 1 y 8 = otros (el código queda en clasificacion_id); VALOR_EXENTO = exento;
--   INGUAT; TIMBRE_PRENSA; galones (el IDP se calcula con las tasas de Parámetros generales); PCT_IVA; CALCULAR_RETENCION y
--   VALOR_RETENCION; CUENTA_MOVTO = cuenta del gasto; DESCRIPCION = justificación; USUARIO y FECHA_INGRESO = quien lo
--   ingresó y cuándo; FECHA_PRESENTACION. El IVA y la base se calculan con la regla del sistema.
--   Hay 2 movimientos de ajuste con total cero o negativo (3-01 caja 1 subcaja 2 movimiento 21, −3.04; 3-02 caja 5 subcaja 23
--   movimiento 4, 0.00): la regla «total mayor que cero» se abre solo para los documentos migrados.
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.

alter table public.caja_documentos add column if not exists origen_anterior text;
alter table public.caja_documentos add column if not exists movimiento_anterior integer;
alter table public.caja_documentos add column if not exists tipo_documento_anterior integer;
alter table public.caja_documentos add column if not exists tipo_documento_id bigint references public.tipos_documento_compra(id);
alter table public.caja_documentos add column if not exists clasificacion_anterior integer;
alter table public.caja_documentos add column if not exists clasificacion_id bigint references public.clasificaciones_compra(id);
alter table public.caja_documentos add column if not exists proveedor_id bigint references public.proveedores(id);
alter table public.caja_documentos add column if not exists valor_anterior numeric(18, 2);
alter table public.caja_documentos add column if not exists total_factura numeric(18, 2);
alter table public.caja_documentos add column if not exists moneda_integracion integer;
alter table public.caja_documentos add column if not exists valor_cambio_anterior numeric(18, 6);
alter table public.caja_documentos add column if not exists anticipo boolean;
alter table public.caja_documentos add column if not exists propina numeric(18, 2);
alter table public.caja_documentos add column if not exists porcentaje_retencion numeric(6, 2);
alter table public.caja_documentos add column if not exists aplica_inguat boolean;
alter table public.caja_documentos add column if not exists cuenta_codigo_anterior text;
alter table public.caja_documentos add column if not exists version_cuenta_anterior integer;
alter table public.caja_documentos add column if not exists cuenta_propina_id bigint references public.cuentas(id);
alter table public.caja_documentos add column if not exists cuenta_propina_codigo_anterior text;
alter table public.caja_documentos add column if not exists version_propina_anterior integer;
alter table public.caja_documentos add column if not exists tipo_factura text;
alter table public.caja_documentos add column if not exists tipo_gasto_anterior text;
alter table public.caja_documentos add column if not exists persona_gasto text;
alter table public.caja_documentos add column if not exists exento_anterior numeric(18, 2);
alter table public.caja_documentos add column if not exists estado_anterior text;
alter table public.caja_documentos add column if not exists valor_mi numeric(18, 2);
alter table public.caja_documentos add column if not exists nombre_recibe text;
alter table public.caja_documentos add column if not exists fecha_ingreso_anterior timestamp;
alter table public.caja_documentos add column if not exists fecha_ing_anterior timestamp;
-- El sistema anterior tiene 2 movimientos de ajuste con total cero o negativo: solo los migrados pueden quedar así.
alter table public.caja_documentos drop constraint if exists caja_documentos_total_check;
alter table public.caja_documentos add constraint caja_documentos_total_check check (total > 0 or origen_anterior = 'MIGRADO');

do $migra$
declare
  v_org bigint; v_gtq bigint; r record; v_loc bigint; v_per bigint; v_prov public.proveedores; g public.parametros_generales;
